import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { color, mix, positionLocal, normalLocal, smoothstep, texture, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    OctahedronGeometry,
    PointLight,
    Color,
  } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'features-ornamental-divider';

  const ownedGeometries = [];
  const ownedMaterials = [];
  const animations = [];
  const loadedTextures = [];
  let disposed = false;

  const makeBasicMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const makeMetalMaterial = (options = {}) => {
    const material = new MeshStandardNodeMaterial({
      color: colors.paper,
      roughness: 0.58,
      metalness: 0.5,
      ...options,
    });
    ownedMaterials.push(material);
    return material;
  };

  const addMesh = (geometry, material, name) => {
    ownedGeometries.push(geometry);
    const mesh = new Mesh(geometry, material);
    mesh.name = name;
    root.add(mesh);
    return mesh;
  };

  const backdropGeometry = new PlaneGeometry(7, 6, 1, 1);
  const backdropMaterial = makeBasicMaterial();
  const backdropV = uv().y;
  backdropMaterial.colorNode = mix(
    color(colors.surface),
    color(colors.ink),
    smoothstep(0.0, 1.0, backdropV),
  );
  const backdrop = addMesh(backdropGeometry, backdropMaterial, 'designed-stage-backdrop');
  backdrop.position.set(0, 0, -2.5);

  const shadowGeometry = new PlaneGeometry(4.8, 0.72, 1, 1);
  const shadowMaterial = makeBasicMaterial({
    transparent: true,
    opacity: 0.46,
    depthWrite: false,
  });
  shadowMaterial.colorNode = color('#000000');
  const shadow = addMesh(shadowGeometry, shadowMaterial, 'divider-contact-shadow');
  shadow.position.set(0, -0.05, -0.18);
  shadow.scale.set(1, 0.28, 1);

  const imageGeometry = new PlaneGeometry(4.8, 0.42, 64, 64);
  const imageMaterial = makeBasicMaterial({
    transparent: true,
    depthWrite: false,
  });
  const imagePlane = addMesh(imageGeometry, imageMaterial, 'machined-parallax-surface');
  imagePlane.position.z = 0.02;

  const imageUv = uv();
  let imageTexture = null;
  let depthTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (disposed) return;
      imageTexture = tex;
      loadedTextures.push(tex);
      imageMaterial.colorNode = texture(tex, imageUv);
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      if (disposed) return;
      depthTexture = tex;
      loadedTextures.push(tex);
      const displacement = texture(tex, uv()).r
        .sub(0.5)
        .mul(0.075);
      imageMaterial.positionNode = positionLocal.add(
        normalLocal.mul(displacement),
      );
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const leftRuleGeometry = new BoxGeometry(1.72, 0.035, 0.06, 4, 2, 2);
  const leftRuleMaterial = makeMetalMaterial();
  const leftRule = addMesh(leftRuleGeometry, leftRuleMaterial, 'left-machined-rule');
  leftRule.position.set(-1.48, 0, 0.09);

  const rightRuleGeometry = new BoxGeometry(1.72, 0.035, 0.06, 4, 2, 2);
  const rightRuleMaterial = makeMetalMaterial();
  const rightRule = addMesh(rightRuleGeometry, rightRuleMaterial, 'right-machined-rule');
  rightRule.position.set(1.48, 0, 0.09);

  const innerLeftGeometry = new BoxGeometry(0.58, 0.012, 0.075, 2, 1, 2);
  const innerLeftMaterial = makeMetalMaterial({
    color: new Color(colors.ink),
    roughness: 0.5,
    metalness: 0.52,
  });
  const innerLeft = addMesh(innerLeftGeometry, innerLeftMaterial, 'inner-left-rule');
  innerLeft.position.set(-0.43, 0, 0.11);

  const innerRightGeometry = new BoxGeometry(0.58, 0.012, 0.075, 2, 1, 2);
  const innerRightMaterial = makeMetalMaterial({
    color: new Color(colors.ink),
    roughness: 0.5,
    metalness: 0.52,
  });
  const innerRight = addMesh(innerRightGeometry, innerRightMaterial, 'inner-right-rule');
  innerRight.position.set(0.43, 0, 0.11);

  const jewelMaterial = makeMetalMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.7,
    roughness: 0.32,
    metalness: 0.42,
  });
  const jewelGeometry = new OctahedronGeometry(0.13, 1);
  const jewel = addMesh(jewelGeometry, jewelMaterial, 'signal-red-center-jewel');
  jewel.position.set(0, 0, 0.18);
  jewel.rotation.z = Math.PI * 0.25;

  const edgeGeometry = new BoxGeometry(4.82, 0.5, 0.025, 1, 1, 1);
  const edgeMaterial = makeBasicMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0,
    depthWrite: false,
  });
  const focusEdge = addMesh(edgeGeometry, edgeMaterial, 'focus-accent-edge');
  focusEdge.position.z = 0.24;
  focusEdge.visible = false;

  const rimLight = new PointLight(colors.accent, 0.72, 3.8, 2);
  rimLight.name = 'accent-rim-light';
  rimLight.position.set(0, 0.35, 1.1);
  root.add(rimLight);

  root.position.y = 0.15;
  const entrance = gsap.to(root.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
    paused: true,
  });
  animations.push(entrance);
  entrance.play();

  const handlers = {
    hover(active = true) {
      if (disposed) return;
      gsap.to(root.position, {
        y: active ? 0.15 : 0,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true,
      });
      gsap.to(root.rotation, {
        z: active ? -0.018 : 0,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: true,
      });
    },

    click() {
      if (disposed) return;
      const press = gsap.timeline();
      press
        .to(root.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'power2.out',
        })
        .to(root.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.42,
          ease: 'back.out(2.2)',
        });
      animations.push(press);
      ctx.emit('hub-features.select', {
        node: 'hub-features-ornamental-divider',
      });
    },

    focus(active = true) {
      if (disposed) return;
      focusEdge.visible = active;
      gsap.to(edgeMaterial, {
        opacity: active ? 0.78 : 0,
        duration: 0.2,
        ease: 'power2.out',
        overwrite: true,
      });
      gsap.to(jewelMaterial, {
        emissiveIntensity: active ? 2.1 : 1.7,
        duration: 0.2,
        ease: 'power2.out',
        overwrite: true,
      });
    },

    move(pointer = {}) {
      if (disposed) return;
      const x = Number(pointer.x ?? pointer.clientX ?? 0);
      const y = Number(pointer.y ?? pointer.clientY ?? 0);
      const nx = Math.max(-1, Math.min(1, x));
      const ny = Math.max(-1, Math.min(1, y));
      gsap.to(imagePlane.rotation, {
        y: nx * 0.035,
        x: -ny * 0.025,
        duration: 0.45,
        ease: 'power2.out',
        overwrite: true,
      });
    },
  };

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const animation of animations) {
      if (animation?.kill) animation.kill();
    }

    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.rotation);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(imagePlane.rotation);
    gsap.killTweensOf(edgeMaterial);
    gsap.killTweensOf(jewelMaterial);

    for (const geometry of ownedGeometries) geometry.dispose();
    for (const material of ownedMaterials) material.dispose();

    root.traverse((object) => {
      if (object.parent) object.parent.remove(object);
    });
  };

  return root;
}
